class BaseLTEvDU:

    def __init__(self, connection_details: ConnectionDetails) -> None:
        self.connection_details = connection_details
        self.sec_v1 = SECv1(
            base_url=connection_details.base_url,
            connection_details=connection_details
        )
        self.asm_v1 = ASMv1(
            base_url=connection_details.base_url,
            connection_details=connection_details
        )
        self.emservice_v1 = EMSERVICEv1(
            base_url=connection_details.base_url,
            connection_details=connection_details
        )
        self.fm_licensed_v1 = FMLicensedv1(
            base_url=connection_details.base_url,
            connection_details=connection_details
        )
        self.cp_config_v1 = CPCONFIGv1(
            base_url=connection_details.base_url,
            connection_details=connection_details
        )
        self.cm_licensed_v1 = CMLicensedv1(
            base_url=connection_details.base_url,
            connection_details=connection_details
        )
        self.agent_v1 = AGENTv1(
            base_url=connection_details.base_url,
            connection_details=connection_details
        )

    def login(self) -> dict:
        """
        Tries sending login request to the 4G vDU.
        If the response status code is 403, it updates the expired password and tries to log in again.
        (password update is necessary for the first login after deployment)

        :raises AuthenticationError: If the login fails.

        :returns: Response of the login request, for example:

            .. code-block:: python

                {
                   "UserId":10000,
                   "Type":"Bearer",
                   "Token":"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJjaXAiOiIxMC4xNTguMTAwLjEiLCJ",
                   "Expires":"2025-03-18T14:34:36+00:00",
                   "LastLogin":"2025-03-18T13:59:16+00:00",
                   "LastFailedLogin":"2025-03-12T14:18:14+00:00",
                   "FailedLoginAttempts":"There is no failed login attempt yet",
                   "PasswordExpirationDate":"Password never expires",
                   "UserType":"local",
                   "ReadOnlyMode":false,
                   "Role":"systemUserAccessMode"
                }
        :rtype: dict
        """
        try:
            return self.sec_v1.login()

        except APIRequestError as e:
            if e.status_code == 403:
                self.asm_v1.update_expired_password()
                self.sec_v1.logout()

                return self.sec_v1.login(password="Nokia@123")

            if e.response.status_code == 401:
                raise AuthenticationError(
                    username=self.connection_details.username, password=self.connection_details.password
                )
            else:
                raise e

    def logout(self) -> None:
        """ Sends logout request to the 4G vDU. """
        self.sec_v1.logout()

    def perform_commissioning(
        self,
        scf_file: str,
        timeout: int
    ) -> dict:
        """
        Perform commissioning by executing steps listed below (this is a temporary solution which should be
        updated when M2M interface is available - feature CB013057 comes to live).

        Steps:
        1. Add plan to staging: POST asm/v1/staged-plans/actions/downloads
        2. Validate plan: POST emservice/v1/staged-plans/{planId}/actions/validations
        3. Check validation results: GET emservice/v1/staged-plans/{planId}/validation-results/{validationId}
        4. Activate plan: POST asm/v1/staged-plans/{plan_id}/operations/activations

        If any of the steps 2-4 fails, the staged plan is deleted using DELETE asm/v1/staged-plans/{plan_id}.

        :param str scf_file: Path of the SCF file which will be used for commissioning.
        :param int timeout: Timeout for the operation.

        :raises APIRequestError: if at any step request fails
        :raises RequestTimeoutError: if any of the steps is not completed within timeout

        :returns: activate plan operation info, for example:

            .. code-block::

                {
                   "basicReport":{
                      "activationErrors":[],
                      "commissioningType":"Full commissioning",
                      "dateAndTime":"2025-03-24T12:06:11+00:00",
                      "planActivationResult":"success",
                      "planValidationResult":"success",
                      "validationErrors":[]
                   },
                   "cmPlanId":"plan_20250324120610_43b9c171-9a58-4fa4-a714-343a9f57f80c",
                   "consistencyReport": [],
                   "id":"o_67d68b37-f63b-473f-95f6-d2174d06fc1e",
                   "procedureState":"planActivate",
                   "status":"success"
                }
        :rtype: dict
        """
        timeout_for_one_step = timeout // 4
        plan_id = self.asm_v1.add_plan_to_staging(scf_file=scf_file, timeout=timeout_for_one_step)["planId"]

        try:
            validation_id = self.emservice_v1.validate_staged_plan(
                plan_id=plan_id, timeout=timeout_for_one_step
            )["validationId"]
            self.emservice_v1.check_validation_results(plan_id=plan_id, validation_id=validation_id)

            return self.asm_v1.activate_validated_plan(plan_id=plan_id, timeout=timeout_for_one_step)

        except Exception as e:
            self.asm_v1.delete_staged_plan(plan_id=plan_id)
            raise e

    def get_vdu_state_data(self) -> dict:
        """ Returns information about the 4G vDU. """
        return self.emservice_v1.get_vdu_state_data()

    def get_current_scf_file(
        self,
        local_dir_path: str,
        file_name: str,
        include_runtime_data: bool,
        include_delta_data: bool,
        timeout: int
    ) -> str:
        """
        Save current plan file to local directory.

        :param str local_dir_path: Local directory path where the SCF file will be saved, for example: "/home/ute"
        :param str file_name: Name of the SCF file with .xml extension, for example: "my_scf.xml"
        :param bool include_runtime_data: If True, runtime data is included in the SCF file. Defaults to False.
        :param bool include_delta_data: If True, planned changes are included in the SCF file.
                                        Defaults to True.
        :param int timeout: Timeout for the operation. Defaults to 30 seconds.

        :returns: Path to the saved SCF file, for example: "/home/ute/my_scf.xml"
        :rtype: str
        """
        return self.emservice_v1.save_plan_to_local(
            plan_id=self.emservice_v1.get_current_plan_id(),
            local_dir_path=local_dir_path,
            file_name=file_name,
            include_delta_data=include_delta_data,
            include_runtime_data=include_runtime_data,
            timeout=timeout
        )

    def get_scf(
        self,
        include_runtime_data: bool,
        include_delta_data: bool,
        timeout: int
    ) -> bytes:
        """
        Get content of the current plan

        :param bool include_runtime_data: If True, runtime data is included in the SCF file. Defaults to False.
        :param bool include_delta_data: If True, planned changes are included in the SCF file.
                                        Defaults to True.
        :param int timeout: Timeout for the operation. Defaults to 30 seconds.

        :returns: SCF content
        :rtype: bytes
        """
        return self.emservice_v1.get_scf(
            plan_id=self.emservice_v1.get_current_plan_id(),
            include_runtime_data=include_runtime_data,
            include_delta_data=include_delta_data,
            timeout=timeout
        )

    def get_snapshot(
        self,
        directory: str,
        coverage: str,
        compressed: bool,
        timeout: int
    ) -> str:
        """
        Triggers local snapshot collection, downloads it and saves to local directory

        :param str directory: local directory where the snapshot will be saved, for example: "/home/ute"
        :param str coverage: coverage of the snapshot, available options:
                             "full", "minor", "fullWithoutRFLogs", "minorWithoutRFLogs", "l1Files", "screl".
                             Defaults to "full"
        :param str compressed: if True, the snapshot files will be compressed to zip. Defaults to True
        :param int timeout: timeout for the operation. Defaults to 300 seconds

        :returns: path to the saved snapshot.

                  If snapshot files are compressed, the zip file path is returned. i.e. /home/ute/Snapshot_20230921-163838.zip

                  If snapshot files are not compressed, the snapshot folder name is returned which is the same as parameter "directory"
        :rtype: str
        """
        operation_id = self.asm_v1.trigger_snapshot_collection(coverage=coverage)["operationId"]

        try:
            snapshot_files = self.asm_v1.collect_snapshot(operation_id=operation_id, timeout=timeout)["files"]
            snapshot_path = self.asm_v1.download_snapshot_files_and_save_to_local(
                operation_id=operation_id,
                snapshot_files=snapshot_files,
                directory=directory,
                compressed=compressed
            )
        except Exception as e:
            self.asm_v1.delete_snapshot_operation(operation_id=operation_id)
            raise e

        self.asm_v1.delete_snapshot_operation(operation_id=operation_id)
        return snapshot_path

